import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse('{"title":"Agile & Sprints","description":"How Agile projects and sprints work in VERA — each sprint carries its own budget and contract value.","frontmatter":{"description":"How Agile projects and sprints work in VERA — each sprint carries its own budget and contract value."},"headers":[],"relativePath":"reference/concepts/sprints.md","filePath":"reference/concepts/sprints.md"}'),i={name:"reference/concepts/sprints.md"};function s(o,e,c,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="agile-sprints" tabindex="-1">Agile &amp; Sprints <a class="header-anchor" href="#agile-sprints" aria-label="Permalink to &quot;Agile &amp; Sprints&quot;">​</a></h1><p>Agile is a project type for iterative delivery. Work is organized into numbered sprints, each with its own contract value and hours budget.</p><hr><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>An Agile project has two levels:</p><p><strong>Parent project</strong> — a named container. No contract value, no budget, no revenue. Just a namespace.</p><p><strong>Sprints</strong> — child projects attached to the parent. Each sprint has:</p><ul><li>A contract value (agreed with the client)</li><li>An hours budget (the work estimate)</li><li>A status (<code>planned</code> or <code>active</code>)</li><li>A sprint number (auto-incremented)</li></ul><hr><h2 id="revenue-recognition" tabindex="-1">Revenue recognition <a class="header-anchor" href="#revenue-recognition" aria-label="Permalink to &quot;Revenue recognition&quot;">​</a></h2><p>Revenue is per-sprint and follows a Fixed Price model:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenue = (hours_logged ÷ hours_budget) × contract_value</span></span>
<span class="line"><span>          capped at contract_value</span></span>
<span class="line"><span>          when sprint_status = &#39;active&#39;</span></span></code></pre></div><p><strong>Planned sprints</strong> ($0 revenue) — The sprint is in the backlog. Work has not started. No revenue is recognized regardless of any hours logged.</p><p><strong>Active sprints</strong> (accruing) — Work is underway. Revenue accrues continuously as hours are logged, up to 100% of <code>contract_value</code>.</p><hr><h2 id="sprint-statuses" tabindex="-1">Sprint statuses <a class="header-anchor" href="#sprint-statuses" aria-label="Permalink to &quot;Sprint statuses {#sprint-statuses}&quot;">​</a></h2><p>There are exactly two statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Revenue</th><th>Meaning</th></tr></thead><tbody><tr><td><code>planned</code></td><td>$0</td><td>Backlog — not yet started</td></tr><tr><td><code>active</code></td><td>Accruing</td><td>Work in progress</td></tr></tbody></table><p>There are no other states. No &quot;completed,&quot; &quot;archived,&quot; or &quot;on hold.&quot; When a sprint is done, log the remaining hours and start the next sprint. If you stop work mid-sprint, keep it <code>active</code> — the revenue recognition reflects actual completion.</p><p>To change status from <code>planned</code> to <code>active</code>, use <code>update_sprint_status</code>. This is done directly without a confirmation prompt.</p><hr><h2 id="sprint-contract-values" tabindex="-1">Sprint contract values <a class="header-anchor" href="#sprint-contract-values" aria-label="Permalink to &quot;Sprint contract values&quot;">​</a></h2><p><strong>Always ask explicitly for each sprint&#39;s contract value.</strong> Never derive it from the parent project or copy it from a previous sprint. Sprint scope and value change — even two weeks apart. VERA will always prompt for this if you don&#39;t provide it.</p><hr><h2 id="creating-a-sprint-sequence" tabindex="-1">Creating a sprint sequence <a class="header-anchor" href="#creating-a-sprint-sequence" aria-label="Permalink to &quot;Creating a sprint sequence&quot;">​</a></h2><ol><li>Create the Agile parent: <code>create_project &quot;Acme App&quot; as Agile</code></li><li>VERA immediately offers to set up Sprint 1</li><li>Provide Sprint 1&#39;s contract value and hours budget: <code>create_sprint</code></li><li>Team logs time against Sprint 1</li><li>When ready for the next sprint: <code>create_sprint</code> again — sprint number auto-increments</li><li>Activate each sprint when work begins: <code>update_sprint_status</code></li></ol><p>Sprint numbers are managed by VERA. Don&#39;t specify them manually.</p><hr><h2 id="agile-summary" tabindex="-1">Agile summary <a class="header-anchor" href="#agile-summary" aria-label="Permalink to &quot;Agile summary&quot;">​</a></h2><p><code>get_agile_summary</code> shows all sprints under a parent Agile project:</p><ul><li>Sprint name and number</li><li>Status (planned / active)</li><li>Hours logged vs. hours budget</li><li>Recognized revenue (Owners only)</li></ul><p>Use this for a complete view of an Agile project&#39;s delivery history and current pipeline.</p><hr><h2 id="work-gate" tabindex="-1">Work gate <a class="header-anchor" href="#work-gate" aria-label="Permalink to &quot;Work gate&quot;">​</a></h2><p>Like T&amp;M, work should stop when a sprint&#39;s <code>hours_budget</code> is exhausted. The mechanism isn&#39;t a hard lock — VERA won&#39;t refuse to log time — but the intent is clear: once the sprint&#39;s budget is used, scope for that sprint is complete. Any additional work should be scoped and contracted as a new sprint.</p><hr><h2 id="agile-vs-fixed-price" tabindex="-1">Agile vs. Fixed Price <a class="header-anchor" href="#agile-vs-fixed-price" aria-label="Permalink to &quot;Agile vs. Fixed Price&quot;">​</a></h2><p>The main difference:</p><table tabindex="0"><thead><tr><th></th><th>Fixed Price</th><th>Agile</th></tr></thead><tbody><tr><td>Structure</td><td>Single project</td><td>Parent + numbered sprints</td></tr><tr><td>Scope change</td><td>Edit the project</td><td>Add a new sprint</td></tr><tr><td>Revenue</td><td>One calculation</td><td>Per-sprint calculations</td></tr><tr><td>Contract value</td><td>Single total</td><td>Per-sprint</td></tr><tr><td>Historical view</td><td>Single timeline</td><td>Sprint-by-sprint history</td></tr></tbody></table><p>If a project is genuinely one fixed scope with one contract, use Fixed Price. Use Agile when the client relationship involves iterative contracting and the scope evolves sprint by sprint.</p>`,40)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
